//! Logging dataflow fragment for events generated by storage dataflows.
//!
//! Storage dataflows hosted on the compute Timely workers log [`StorageEvent`]s to the
//! [`mz_storage::logging::LOGGER_NAME`] logger. Storage never retracts its events. This
//! fragment retracts every row of a dataflow when it observes that dataflow's
//! [`StorageEvent::DataflowShutdown`], which the Timely logging fragment emits.

use std::collections::{BTreeMap, BTreeSet};
use std::fmt::{Display, Write};
use std::rc::Rc;
use std::time::Duration;

use columnar::{Columnar, Index, Ref};
use mz_compute_client::logging::{LoggingConfig, StorageLog};
use mz_ore::cast::CastFrom;
use mz_repr::{Datum, Diff, GlobalId, Row, RowRef, Timestamp};
use mz_row_spine::RowRowBuilder;
use mz_storage::logging::{
    DataflowGlobalReference, DataflowShutdownReference, StageMappingReference, StorageEvent,
    StorageEventReference,
};
use mz_timely_util::columnar::builder::ColumnBuilder;
use mz_timely_util::columnar::{Col2ValBatcher, Column, batcher, columnar_exchange};
use mz_timely_util::replay::MzReplay;
use timely::dataflow::Scope;
use timely::dataflow::channels::pact::{ExchangeCore, Pipeline};
use timely::dataflow::operators::generic::OutputBuilder;
use timely::dataflow::operators::generic::builder_rc::OperatorBuilder;
use timely::dataflow::operators::generic::operator::empty;
use tracing::error;

use crate::extensions::arrange::MzArrangeCore;
use crate::logging::{
    EventQueue, LogCollection, LogVariant, OutputSessionColumnar, PermutedRowPacker, Update,
};
use crate::typedefs::RowRowSpine;

/// The return type of the [`construct`] function.
pub(super) struct Return {
    /// Collections returned by [`construct`].
    pub collections: BTreeMap<LogVariant, LogCollection>,
}

/// Constructs the logging dataflow fragment for storage logs.
pub(super) fn construct<'scope>(
    scope: Scope<'scope, Timestamp>,
    config: &LoggingConfig,
    event_queue: EventQueue<Column<(Duration, StorageEvent)>>,
) -> Return {
    let logging_interval_ms = std::cmp::max(1, config.interval.as_millis());

    scope.scoped("storage logging", move |scope| {
        let (logs, token) = if config.enable_logging {
            event_queue.links.mz_replay(
                scope,
                "storage logs",
                config.interval,
                event_queue.activator,
            )
        } else {
            let token: Rc<dyn std::any::Any> = Rc::new(Box::new(()));
            (empty(scope), token)
        };

        let mut demux = OperatorBuilder::new("Storage Logging Demux".to_string(), scope.clone());
        let mut input = demux.new_input(logs, Pipeline);
        let (dataflow_global_ids_out, dataflow_global_ids) = demux.new_output();
        let mut dataflow_global_ids_out = OutputBuilder::from(dataflow_global_ids_out);
        let (stage_mapping_out, stage_mapping) = demux.new_output();
        let mut stage_mapping_out = OutputBuilder::from(stage_mapping_out);

        let mut demux_state = DemuxState::new(scope.index());
        demux.build(move |_capability| {
            move |_frontiers| {
                let mut dataflow_global_ids = dataflow_global_ids_out.activate();
                let mut stage_mapping = stage_mapping_out.activate();

                input.for_each(|cap, data| {
                    let mut output = DemuxOutput {
                        dataflow_global_ids: dataflow_global_ids.session_with_builder(&cap),
                        stage_mapping: stage_mapping.session_with_builder(&cap),
                    };
                    for (time, event) in data.borrow().into_index_iter() {
                        let ts = interval_ts(time, logging_interval_ms);
                        demux_state.handle(event, ts, &mut output);
                    }
                });
            }
        });

        let logs = [
            (StorageLog::DataflowGlobal, dataflow_global_ids),
            (StorageLog::StageMapping, stage_mapping),
        ];

        let mut collections = BTreeMap::new();
        for (variant, stream) in logs {
            let variant = LogVariant::Storage(variant);
            if config.index_logs.contains_key(&variant) {
                let exchange = ExchangeCore::<ColumnBuilder<_>, _>::new_core(
                    columnar_exchange::<Row, Row, Timestamp, Diff>,
                );
                let trace = stream
                    .mz_arrange_core::<
                        _,
                        batcher::Chunker<_>,
                        Col2ValBatcher<_, _, _, _>,
                        RowRowBuilder<_, _>,
                        RowRowSpine<_, _>,
                    >(exchange, &format!("Arrange {variant:?}"))
                    .trace;
                let collection = LogCollection {
                    trace,
                    token: Rc::clone(&token),
                };
                collections.insert(variant, collection);
            }
        }

        Return { collections }
    })
}

/// Rounds an event time up to the next logging interval boundary.
fn interval_ts(time: Duration, interval_ms: u128) -> Timestamp {
    let rounded = (time.as_millis() / interval_ms + 1) * interval_ms;
    rounded.try_into().expect("must fit")
}

/// Format the given value and pack it into a `Datum::String`, reusing `scratch`.
fn make_string_datum<V: Display>(value: V, scratch: &mut String) -> Datum<'_> {
    scratch.clear();
    write!(scratch, "{}", value).expect("writing to a `String` can't fail");
    Datum::String(scratch)
}

/// A logged stage mapping, retained until its dataflow shuts down.
struct StageRow {
    global_id: GlobalId,
    stage_id: u64,
    parent_stage_id: Option<u64>,
    nesting: u8,
    stage: String,
    operator_id_start: usize,
    operator_id_end: usize,
}

/// Bundled output sessions used by the demux operator.
struct DemuxOutput<'a, 'b> {
    dataflow_global_ids: OutputSessionColumnar<'a, 'b, Update<(Row, Row)>>,
    stage_mapping: OutputSessionColumnar<'a, 'b, Update<(Row, Row)>>,
}

/// State maintained by the demux operator.
struct DemuxState {
    /// The index of this worker.
    worker_id: usize,
    /// A reusable scratch string for formatting IDs.
    scratch_string: String,
    /// The `GlobalId`s logged for each dataflow.
    dataflow_global_ids: BTreeMap<usize, BTreeSet<GlobalId>>,
    /// The stage mappings logged for each dataflow.
    stage_mappings: BTreeMap<usize, Vec<StageRow>>,
    dataflow_global_packer: PermutedRowPacker,
    stage_mapping_packer: PermutedRowPacker,
}

impl DemuxState {
    fn new(worker_id: usize) -> Self {
        Self {
            worker_id,
            scratch_string: String::new(),
            dataflow_global_ids: Default::default(),
            stage_mappings: Default::default(),
            dataflow_global_packer: PermutedRowPacker::new(StorageLog::DataflowGlobal),
            stage_mapping_packer: PermutedRowPacker::new(StorageLog::StageMapping),
        }
    }

    fn handle(&mut self, event: Ref<'_, StorageEvent>, ts: Timestamp, output: &mut DemuxOutput) {
        match event {
            StorageEventReference::DataflowGlobal(global) => {
                self.handle_dataflow_global(global, ts, output)
            }
            StorageEventReference::StageMapping(mapping) => {
                self.handle_stage_mapping(mapping, ts, output)
            }
            StorageEventReference::DataflowShutdown(shutdown) => {
                self.handle_dataflow_shutdown(shutdown, ts, output)
            }
        }
    }

    fn handle_dataflow_global(
        &mut self,
        DataflowGlobalReference {
            dataflow_index,
            global_id,
        }: Ref<'_, mz_storage::logging::DataflowGlobal>,
        ts: Timestamp,
        output: &mut DemuxOutput,
    ) {
        let global_id = Columnar::into_owned(global_id);
        let inserted = self
            .dataflow_global_ids
            .entry(dataflow_index)
            .or_default()
            .insert(global_id);
        if !inserted {
            error!(%dataflow_index, %global_id, "storage dataflow already logged this GlobalId");
            return;
        }

        let datum = self.pack_dataflow_global(dataflow_index, global_id);
        output.dataflow_global_ids.give((datum, ts, Diff::ONE));
    }

    fn handle_stage_mapping(
        &mut self,
        mapping: Ref<'_, mz_storage::logging::StageMapping>,
        ts: Timestamp,
        output: &mut DemuxOutput,
    ) {
        let StageMappingReference {
            dataflow_index,
            global_id,
            stage_id,
            parent_stage_id,
            nesting,
            stage,
            operator_id_start,
            operator_id_end,
        } = mapping;
        let row = StageRow {
            global_id: Columnar::into_owned(global_id),
            stage_id: Columnar::into_owned(stage_id),
            parent_stage_id: Columnar::into_owned(parent_stage_id),
            nesting: Columnar::into_owned(nesting),
            stage: Columnar::into_owned(stage),
            operator_id_start: Columnar::into_owned(operator_id_start),
            operator_id_end: Columnar::into_owned(operator_id_end),
        };

        let datum = self.pack_stage_mapping(dataflow_index, &row);
        output.stage_mapping.give((datum, ts, Diff::ONE));

        self.stage_mappings
            .entry(dataflow_index)
            .or_default()
            .push(row);
    }

    fn handle_dataflow_shutdown(
        &mut self,
        DataflowShutdownReference { dataflow_index }: Ref<
            '_,
            mz_storage::logging::DataflowShutdown,
        >,
        ts: Timestamp,
        output: &mut DemuxOutput,
    ) {
        for global_id in self
            .dataflow_global_ids
            .remove(&dataflow_index)
            .unwrap_or_default()
        {
            let datum = self.pack_dataflow_global(dataflow_index, global_id);
            output
                .dataflow_global_ids
                .give((datum, ts, Diff::MINUS_ONE));
        }
        for row in self
            .stage_mappings
            .remove(&dataflow_index)
            .unwrap_or_default()
        {
            let datum = self.pack_stage_mapping(dataflow_index, &row);
            output.stage_mapping.give((datum, ts, Diff::MINUS_ONE));
        }
    }

    fn pack_dataflow_global(
        &mut self,
        dataflow_index: usize,
        global_id: GlobalId,
    ) -> (&RowRef, &RowRef) {
        self.dataflow_global_packer.pack_slice(&[
            Datum::UInt64(u64::cast_from(dataflow_index)),
            Datum::UInt64(u64::cast_from(self.worker_id)),
            make_string_datum(global_id, &mut self.scratch_string),
        ])
    }

    fn pack_stage_mapping(&mut self, dataflow_index: usize, row: &StageRow) -> (&RowRef, &RowRef) {
        self.stage_mapping_packer.pack_slice(&[
            Datum::UInt64(u64::cast_from(dataflow_index)),
            make_string_datum(row.global_id, &mut self.scratch_string),
            Datum::UInt64(row.stage_id),
            Datum::UInt64(u64::cast_from(self.worker_id)),
            Datum::String(&row.stage),
            row.parent_stage_id.map_or(Datum::Null, Datum::UInt64),
            Datum::UInt16(u16::from(row.nesting)),
            Datum::UInt64(u64::cast_from(row.operator_id_start)),
            Datum::UInt64(u64::cast_from(row.operator_id_end)),
        ])
    }
}
